    matches = []
    for _, row in data.iterrows():
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        resp = row['response']

        ttb_winner = None
        for i in range(len(a)):
            if a[i] > b[i]:
                ttb_winner = 0
                break
            elif b[i] > a[i]:
                ttb_winner = 1
                break

        if ttb_winner is not None:
            matches.append(1.0 if resp == ttb_winner else 0.0)

    if not matches:
        return 0.5
    return float(np.mean(matches))

